import{I as e,o as p,c as t,b6 as l,J as h,w as r,j as a,a as o}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"The Mom Test：如何通过用户访谈验证需求","description":"面向零基础读者的 The Mom Test 入门文章。学会避免礼貌性反馈，围绕真实行为、具体事实和已有问题做用户访谈，把“听起来不错”变成更可靠的需求判断。","frontmatter":{"title":"The Mom Test：如何通过用户访谈验证需求","description":"面向零基础读者的 The Mom Test 入门文章。学会避免礼貌性反馈，围绕真实行为、具体事实和已有问题做用户访谈，把“听起来不错”变成更可靠的需求判断。"},"headers":[],"relativePath":"zh-cn/stage-1/appendix-mom-test/index.md","filePath":"zh-cn/stage-1/appendix-mom-test/index.md"}'),d={name:"zh-cn/stage-1/appendix-mom-test/index.md"},m=Object.assign(d,{setup(c){const n="约 <strong>1.5 小时</strong>";return(b,s)=>{const i=e("ChapterIntroduction");return p(),t("div",null,[s[1]||(s[1]=l('<h1 id="the-mom-test-如何通过用户访谈验证需求" tabindex="-1">The Mom Test：如何通过用户访谈验证需求 <a class="header-anchor" href="#the-mom-test-如何通过用户访谈验证需求" aria-label="Permalink to “The Mom Test：如何通过用户访谈验证需求”">​</a></h1><p><a id="top-mom"></a></p><h2 id="本章导读" tabindex="-1">本章导读 <a class="header-anchor" href="#本章导读" aria-label="Permalink to “本章导读”">​</a></h2>',3)),h(i,{duration:n,tags:["用户访谈","需求验证","用户研究","产品调研"],coreOutput:"1 组更能问出真实信息的访谈问题",expectedOutput:"不再把用户的礼貌性鼓励当成验证，而能用真实行为判断方向"},{default:r(()=>[...s[0]||(s[0]=[a("p",null,"很多人第一次做产品调研时，以为最重要的是“找人聊聊”。于是他们去问朋友、同事，甚至家人：",-1),a("ul",null,[a("li",null,"你觉得我这个想法怎么样？"),a("li",null,"如果有这样一个产品，你会不会用？"),a("li",null,"这个功能听起来是不是还不错？")],-1),a("p",null,"对方往往也会给出非常鼓舞人的反馈：",-1),a("ul",null,[a("li",null,"挺好的啊"),a("li",null,"听起来很有用"),a("li",null,"我觉得你可以试试")],-1),a("p",null,"问题在于，这些回答通常并不能帮你做判断。它们更像是礼貌、支持，或者一种不想当场扫你兴的自然反应。你以为自己得到了“市场验证”，其实只是收集了一堆很难用来决策的安慰。",-1),a("p",null,[o("The Mom Test 这套方法，就是专门用来解决这个问题的。它提醒我们："),a("strong",null,"不是用户在故意骗你，而是你问问题的方式，天然会把对方引向好听但没用的回答。")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：看完后，你会更清楚怎么和用户聊天，才不会只听到“听起来不错”，而是真的问出能帮你判断方向的信息。</p><p><strong>行动项</strong>：把你原本想问的 5 个问题改掉，优先问“最近一次发生在什么时候”“你当时怎么处理”。</p><p><strong>结果</strong>：你会更容易分清哪些是意见，哪些才是真正能支撑判断的证据。</p><p><strong>关键词跳转</strong>：<a href="#mom-what">The Mom Test 是什么</a> · <a href="#mom-principles">三个核心原则</a> · <a href="#mom-ai">AI 怎么帮你</a></p></div><h2 id="你将学到以下内容" tabindex="-1">你将学到以下内容 <a class="header-anchor" href="#你将学到以下内容" aria-label="Permalink to “你将学到以下内容”">​</a></h2><ol><li>The Mom Test 到底在解决什么问题，为什么很多“用户调研”其实没有调研到真实信息</li><li>这套方法最核心的几个原则：少问意见，多问行为；少问假设，多问事实</li><li>怎样把一个容易得到假阳性反馈的问题，改成更有价值的访谈问题</li><li>如何把 The Mom Test 和 JTBD、需求验证、MVP 判断连起来使用</li></ol><p><a id="mom-what"></a></p><h2 id="_1-the-mom-test-到底是什么" tabindex="-1"><a href="#top-mom">1. The Mom Test 到底是什么</a> <a class="header-anchor" href="#_1-the-mom-test-到底是什么" aria-label="Permalink to “1. The Mom Test 到底是什么”">​</a></h2><p>The Mom Test 来自 Rob Fitzpatrick 的同名书籍。它的名字听起来有点像玩笑，但点得非常准：</p><p><strong>就算是你妈妈，也很难直接告诉你“这是个烂想法”。</strong></p><p>原因不是她不诚实，而是：</p><ul><li>她不想伤害你</li><li>她会下意识鼓励你</li><li>她很容易顺着你的表达方式回答</li></ul><p>其实不只是妈妈，朋友、同事、前同学，甚至很多陌生人，在面对你的产品想法时，也常常会给出类似的“正向反馈”。这不代表需求真的存在，只代表你把问题问成了一个很容易得到好听答案的形式。</p><p>所以，The Mom Test 的重点从来不是“别问妈妈”，而是：</p><p><strong>别把问题问成任何人都会顺着你回答的样子。</strong></p><p>这套方法真正想教你的，是如何通过对话，拿到更接近真实需求的信息，而不是收集一堆让自己感觉良好的评论。</p><h2 id="_2-它解决的核心问题是什么" tabindex="-1">2. 它解决的核心问题是什么 <a class="header-anchor" href="#_2-它解决的核心问题是什么" aria-label="Permalink to “2. 它解决的核心问题是什么”">​</a></h2><p>The Mom Test 主要解决的是一种非常常见的认知错觉：</p><p><strong>把礼貌性的积极反馈，当成真实需求。</strong></p><p>比如你问：</p><ul><li>你觉得这个 App 想法怎么样？</li><li>如果我做一个 AI 帮你写简历的工具，你会用吗？</li><li>这个功能是不是很有价值？</li></ul><p>这些问题的共同特点是：</p><ul><li>它们都在问“意见”</li><li>它们都带着一点暗示</li><li>它们都在谈一个还没发生的未来</li></ul><p>而人对“意见”和“未来假设”的回答，通常都不稳定。很多人会高估自己的兴趣、高估自己的执行力，也会高估自己未来的购买意愿。</p><p>所以 The Mom Test 提醒你：</p><ul><li>不要太相信别人对你点子的评价</li><li>不要太相信别人对未来行为的预测</li><li>要尽量回到用户已经发生过的真实行为里</li></ul><p>因为和“你会不会用”相比，“你上次怎么处理这件事的”往往更接近真相。</p><p><a id="mom-principles"></a></p><h2 id="_3-三个最核心的原则" tabindex="-1"><a href="#top-mom">3. 三个最核心的原则</a> <a class="header-anchor" href="#_3-三个最核心的原则" aria-label="Permalink to “3. 三个最核心的原则”">​</a></h2><p>如果你只想先记住最重要的部分，可以先记下面这三个原则。</p><h3 id="_3-1-少谈你的点子-多谈用户过去的真实经历" tabindex="-1">3.1 少谈你的点子，多谈用户过去的真实经历 <a class="header-anchor" href="#_3-1-少谈你的点子-多谈用户过去的真实经历" aria-label="Permalink to “3.1 少谈你的点子，多谈用户过去的真实经历”">​</a></h3><p>很多无效访谈一开场就讲自己的方案，讲自己多么兴奋，讲自己准备做什么产品。问题是，一旦你讲得太多，对方就很容易切换到“配合你”“鼓励你”的状态。</p><p>相比之下，更好的方式是把重点放在对方的经历上：</p><ul><li>最近一次遇到这个问题是什么时候？</li><li>当时你在做什么？</li><li>你最后是怎么处理的？</li><li>哪一步最麻烦？</li></ul><p>你会发现，这类问题能更自然地把对话带回现实，而不是停留在想象中的偏好。</p><h3 id="_3-2-少问抽象意见-多问具体事实" tabindex="-1">3.2 少问抽象意见，多问具体事实 <a class="header-anchor" href="#_3-2-少问抽象意见-多问具体事实" aria-label="Permalink to “3.2 少问抽象意见，多问具体事实”">​</a></h3><p>“我觉得这个功能挺好”“听起来不错”“好像有点用”，这些表达都太抽象了，很难指导产品决策。</p><p>更有价值的信息通常长这样：</p><ul><li>我上周刚为了这件事折腾了 2 小时</li><li>我现在是用 Excel 加微信硬撑</li><li>我上个月已经为类似工具花过钱</li><li>我最怕的是做错，不是做慢</li></ul><p>这些才是真正能帮你判断问题强度、频率和付费可能性的信息。</p><h3 id="_3-3-少问用户想要什么方案-多看他现在怎么解决问题" tabindex="-1">3.3 少问用户想要什么方案，多看他现在怎么解决问题 <a class="header-anchor" href="#_3-3-少问用户想要什么方案-多看他现在怎么解决问题" aria-label="Permalink to “3.3 少问用户想要什么方案，多看他现在怎么解决问题”">​</a></h3><p>用户很擅长描述自己的困扰，但不一定擅长设计解决方案。</p><p>如果你问：</p><ul><li>你想不想要一个 AI 帮你自动做这个？</li><li>你觉得加个智能功能有没有帮助？</li></ul><p>你得到的，通常只是对某个方案的模糊态度，而不是需求本身。</p><p>更好的问题是：</p><ul><li>你现在用什么方法处理这个问题？</li><li>为什么你会选择这种方式？</li><li>它哪里不够好？</li></ul><p>看清现有替代方案，往往比直接问“你想要什么”更重要。</p><h2 id="_4-为什么人们总会给你好听但没用的回答" tabindex="-1">4. 为什么人们总会给你好听但没用的回答 <a class="header-anchor" href="#_4-为什么人们总会给你好听但没用的回答" aria-label="Permalink to “4. 为什么人们总会给你好听但没用的回答”">​</a></h2><p>如果你能理解这件事，做访谈时就会少很多误判。</p><h3 id="_4-1-人会下意识地保持礼貌" tabindex="-1">4.1 人会下意识地保持礼貌 <a class="header-anchor" href="#_4-1-人会下意识地保持礼貌" aria-label="Permalink to “4.1 人会下意识地保持礼貌”">​</a></h3><p>尤其当对话对象和你有关系时，对方很难直接说：</p><ul><li>这个方向听起来不太行</li><li>我根本不会用</li><li>这个问题对我没那么重要</li></ul><p>他更可能说“挺好的”“有机会可以做做看”。</p><h3 id="_4-2-人会高估未来的自己" tabindex="-1">4.2 人会高估未来的自己 <a class="header-anchor" href="#_4-2-人会高估未来的自己" aria-label="Permalink to “4.2 人会高估未来的自己”">​</a></h3><p>很多人真心相信自己未来会：</p><ul><li>更自律</li><li>更愿意学习</li><li>更愿意付费</li><li>更愿意尝试新工具</li></ul><p>所以“如果有的话我应该会用”这句话，常常并不等于未来真的会用。</p><h3 id="_4-3-你的提问方式本身就在引导答案" tabindex="-1">4.3 你的提问方式本身就在引导答案 <a class="header-anchor" href="#_4-3-你的提问方式本身就在引导答案" aria-label="Permalink to “4.3 你的提问方式本身就在引导答案”">​</a></h3><p>当你问：</p><ul><li>我这个想法是不是挺好？</li><li>这个功能对你来说是不是很有帮助？</li></ul><p>你其实已经偷偷把“正确答案”塞进问题里了。</p><p>这也是为什么 The Mom Test 特别强调：<strong>不要把访谈做成你在寻找认可。</strong></p><h2 id="_5-直接对比-什么问题容易问废-什么问题更有价值" tabindex="-1">5. 直接对比：什么问题容易问废，什么问题更有价值 <a class="header-anchor" href="#_5-直接对比-什么问题容易问废-什么问题更有价值" aria-label="Permalink to “5. 直接对比：什么问题容易问废，什么问题更有价值”">​</a></h2><p>下面这些对照，几乎是每个新手都会用到的。</p><table tabindex="0"><thead><tr><th>容易问废的问题</th><th>更有价值的问题</th></tr></thead><tbody><tr><td>你觉得我这个想法怎么样？</td><td>你最近一次遇到这个问题是什么时候？</td></tr><tr><td>如果有这个产品你会用吗？</td><td>你现在是怎么处理这件事的？</td></tr><tr><td>你愿意为这个功能付费吗？</td><td>你上次为了这个问题花过钱吗？花在什么上？</td></tr><tr><td>你觉得这个功能重要吗？</td><td>这个流程里最烦、最慢、最不放心的是哪一步？</td></tr><tr><td>你想不想要一个 AI 帮你自动做？</td><td>你现在为什么还没有找到更顺手的解决办法？</td></tr></tbody></table><p>这张表最重要的不是具体句子，而是背后的方向：</p><ul><li>从意见走向事实</li><li>从未来走向过去</li><li>从你的方案走向用户的问题</li></ul><h2 id="_6-一个零基础也能立刻用的访谈节奏" tabindex="-1">6. 一个零基础也能立刻用的访谈节奏 <a class="header-anchor" href="#_6-一个零基础也能立刻用的访谈节奏" aria-label="Permalink to “6. 一个零基础也能立刻用的访谈节奏”">​</a></h2><p>如果你现在就想去找人聊，可以直接按下面这个顺序来。</p><h3 id="_6-1-开场-说明你在学习-不是在推销" tabindex="-1">6.1 开场：说明你在学习，不是在推销 <a class="header-anchor" href="#_6-1-开场-说明你在学习-不是在推销" aria-label="Permalink to “6.1 开场：说明你在学习，不是在推销”">​</a></h3><p>比如：</p><blockquote><p>我最近在研究大家怎么处理这类问题，想先了解真实情况，不是来卖东西的。</p></blockquote><p>这种表达会让对方更容易放下“我要给你积极反馈”的心理负担。</p><h3 id="_6-2-从最近一次真实经历开始问" tabindex="-1">6.2 从最近一次真实经历开始问 <a class="header-anchor" href="#_6-2-从最近一次真实经历开始问" aria-label="Permalink to “6.2 从最近一次真实经历开始问”">​</a></h3><p>可以先从这类问题开始：</p><ul><li>最近一次遇到这个问题是什么时候？</li><li>当时发生了什么？</li><li>你第一反应是怎么处理的？</li></ul><p>一旦对话进入具体事件，信息质量通常会明显提升。</p><h3 id="_6-3-往下追问行为、成本和替代方案" tabindex="-1">6.3 往下追问行为、成本和替代方案 <a class="header-anchor" href="#_6-3-往下追问行为、成本和替代方案" aria-label="Permalink to “6.3 往下追问行为、成本和替代方案”">​</a></h3><p>继续问：</p><ul><li>你现在用什么办法解决？</li><li>这个办法最不舒服的地方是什么？</li><li>你为此花过多少时间、钱或者精力？</li><li>你试过别的方法吗？为什么没继续用？</li></ul><h3 id="_6-4-最后再判断痛感和优先级" tabindex="-1">6.4 最后再判断痛感和优先级 <a class="header-anchor" href="#_6-4-最后再判断痛感和优先级" aria-label="Permalink to “6.4 最后再判断痛感和优先级”">​</a></h3><p>你不需要直接问“痛不痛”，可以从细节里判断：</p><ul><li>他是不是经常遇到</li><li>他是不是已经在主动补救</li><li>他是不是已经愿意为此付出成本</li><li>他在讲这件事时是不是带着明显情绪</li></ul><p>这些都比一句“这是不是你的痛点”更有用。</p><h2 id="_7-一个更完整的例子" tabindex="-1">7. 一个更完整的例子 <a class="header-anchor" href="#_7-一个更完整的例子" aria-label="Permalink to “7. 一个更完整的例子”">​</a></h2><p>假设你想做一个“AI 帮大学生改简历”的产品。</p><h3 id="错误问法" tabindex="-1">错误问法 <a class="header-anchor" href="#错误问法" aria-label="Permalink to “错误问法”">​</a></h3><p>你去问同学：</p><blockquote><p>我想做一个 AI 简历优化工具，你觉得怎么样？<br> 如果它能根据岗位自动改简历，你会不会用？</p></blockquote><p>这时候，对方很可能会说：</p><ul><li>听起来挺好</li><li>我觉得应该有用</li><li>如果免费我会试试</li></ul><p>这些回答几乎没有办法帮你判断需求到底强不强。</p><h3 id="更好的问法" tabindex="-1">更好的问法 <a class="header-anchor" href="#更好的问法" aria-label="Permalink to “更好的问法”">​</a></h3><p>你可以改成：</p><blockquote><p>你最近一次改简历是什么时候？<br> 当时为什么要改？<br> 你是怎么改的？<br> 哪一步最卡？<br> 你有没有找过别人帮你看？<br> 你以前为简历这件事花过钱或者花过很多时间吗？</p></blockquote><p>通过这些问题，你可能得到的信息会是：</p><ul><li>很多人不是不会写，而是不知道怎么针对不同岗位改写</li><li>他们最痛的不是排版，而是“不知道哪些经历值得写”</li><li>他们会拖延，不是因为懒，而是因为每次改简历都很消耗</li><li>他们已经在用学长建议、模板网站、AI 工具和朋友帮看来勉强解决</li></ul><p>这时候，你离真实问题就近得多了。</p><h2 id="_8-the-mom-test-和-jtbd-怎么配合用" tabindex="-1">8. The Mom Test 和 JTBD 怎么配合用 <a class="header-anchor" href="#_8-the-mom-test-和-jtbd-怎么配合用" aria-label="Permalink to “8. The Mom Test 和 JTBD 怎么配合用”">​</a></h2><p>如果说 JTBD 帮你看清“用户想完成什么进展”，那么 The Mom Test 更像是在教你：</p><p><strong>怎么通过访谈，确认这个 job 是不是真的存在。</strong></p><p>你完全可以把两者接起来使用：</p><ol><li>先用 JTBD 假设一个 job</li><li>再用 The Mom Test 的方式，去问用户最近一次真实经历</li><li>看看这个 job 是否真的高频、真实、值得优先做</li></ol><p>比如你的 JTBD 假设是：</p><blockquote><p>当我准备投递实习时，我想快速把旧简历改成贴合岗位的版本，以便尽快完成投递。</p></blockquote><p>那你就可以用 The Mom Test 风格的问题去验证：</p><ul><li>你最近一次投递是什么时候？</li><li>当时你是怎么改简历的？</li><li>哪一段最难写？</li><li>你改完之后怎么判断它够不够好？</li></ul><p>这样，方法就连起来了：</p><ul><li>JTBD 帮你定义需求假设</li><li>The Mom Test 帮你访谈验证假设</li></ul><h2 id="_9-新手做用户访谈时最常见的误区" tabindex="-1">9. 新手做用户访谈时最常见的误区 <a class="header-anchor" href="#_9-新手做用户访谈时最常见的误区" aria-label="Permalink to “9. 新手做用户访谈时最常见的误区”">​</a></h2><h3 id="_9-1-把访谈做成产品介绍会" tabindex="-1">9.1 把访谈做成产品介绍会 <a class="header-anchor" href="#_9-1-把访谈做成产品介绍会" aria-label="Permalink to “9.1 把访谈做成产品介绍会”">​</a></h3><p>你一讲太多自己的想法，对方就容易开始配合你，而不是告诉你真实情况。</p><h3 id="_9-2-访谈对象全是熟人" tabindex="-1">9.2 访谈对象全是熟人 <a class="header-anchor" href="#_9-2-访谈对象全是熟人" aria-label="Permalink to “9.2 访谈对象全是熟人”">​</a></h3><p>熟人不是不能聊，但熟人更容易鼓励你。你至少需要混合一些更接近真实用户的人，而不是只找支持你的人。</p><h3 id="_9-3-过早追着问功能" tabindex="-1">9.3 过早追着问功能 <a class="header-anchor" href="#_9-3-过早追着问功能" aria-label="Permalink to “9.3 过早追着问功能”">​</a></h3><p>如果你还没搞清楚问题，就开始追问按钮、界面、功能细节，通常是在太早进入解决方案。</p><h3 id="_9-4-把一句-我会用-当成验证结果" tabindex="-1">9.4 把一句“我会用”当成验证结果 <a class="header-anchor" href="#_9-4-把一句-我会用-当成验证结果" aria-label="Permalink to “9.4 把一句“我会用”当成验证结果”">​</a></h3><p>访谈最多帮你判断方向，不等于已经完成验证。真正的验证，最终还是要看用户是否愿意付出真实成本，比如时间、切换成本、试用行为，甚至付费。</p><h3 id="_9-5-访谈结束后不整理" tabindex="-1">9.5 访谈结束后不整理 <a class="header-anchor" href="#_9-5-访谈结束后不整理" aria-label="Permalink to “9.5 访谈结束后不整理”">​</a></h3><p>如果你聊完就放着，信息很快会变成模糊印象。最好尽快整理：</p><ul><li>出现频率高的问题</li><li>用户原话里的情绪词</li><li>当前替代方案</li><li>已经付出的成本</li><li>你自己的新判断</li></ul><h2 id="_10-可以直接复制去用的问题清单" tabindex="-1">10. 可以直接复制去用的问题清单 <a class="header-anchor" href="#_10-可以直接复制去用的问题清单" aria-label="Permalink to “10. 可以直接复制去用的问题清单”">​</a></h2><p>如果你想尽快开始，这里有一组足够通用的问题。</p><h3 id="开场问题" tabindex="-1">开场问题 <a class="header-anchor" href="#开场问题" aria-label="Permalink to “开场问题”">​</a></h3><ul><li>最近一次你遇到这个问题是什么时候？</li><li>当时具体发生了什么？</li></ul><h3 id="行为问题" tabindex="-1">行为问题 <a class="header-anchor" href="#行为问题" aria-label="Permalink to “行为问题”">​</a></h3><ul><li>你当时是怎么处理的？</li><li>你为什么会选择这种方式？</li></ul><h3 id="成本问题" tabindex="-1">成本问题 <a class="header-anchor" href="#成本问题" aria-label="Permalink to “成本问题”">​</a></h3><ul><li>这件事一般会花掉你多少时间或精力？</li><li>你有没有为了解决它花过钱？</li></ul><h3 id="替代方案问题" tabindex="-1">替代方案问题 <a class="header-anchor" href="#替代方案问题" aria-label="Permalink to “替代方案问题”">​</a></h3><ul><li>你试过别的工具或办法吗？</li><li>为什么最后没有继续用？</li></ul><h3 id="收尾问题" tabindex="-1">收尾问题 <a class="header-anchor" href="#收尾问题" aria-label="Permalink to “收尾问题”">​</a></h3><ul><li>如果以后还遇到同样的问题，你觉得最理想的解决方式应该是什么样？</li></ul><p>注意，这个收尾问题可以问，但最好放在后面。因为前面你更需要拿到事实，而不是愿望。</p><h2 id="_11-小结" tabindex="-1">11. 小结 <a class="header-anchor" href="#_11-小结" aria-label="Permalink to “11. 小结”">​</a></h2><p>The Mom Test 最重要的贡献，不是给你一套“更会聊天”的技巧，而是帮你建立一种更清醒的判断方式：</p><ul><li>不要太快相信别人对你点子的夸奖</li><li>不要把“如果有我会用”当成真实需求</li><li>不要让访谈变成你在寻找认可</li></ul><p>真正有价值的访谈，应该尽量回到这些东西上：</p><ul><li>用户最近一次真实经历</li><li>他现在怎么处理</li><li>他已经付出了什么成本</li><li>他在哪些地方明显不舒服</li></ul><p>当你开始这样问，你得到的信息虽然有时没那么好听，但通常更有用。<br> 而做产品时，<strong>有用的真相，永远比好听的鼓励更重要。</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-如何利用-ai-帮你做用户访谈" tabindex="-1"><a href="#top-mom">12. 如何利用 AI 帮你做用户访谈</a> <a class="header-anchor" href="#_12-如何利用-ai-帮你做用户访谈" aria-label="Permalink to “12. 如何利用 AI 帮你做用户访谈”">​</a></h2><p>The Mom Test 本质上还是一套“和真人聊”的方法，所以 AI 不能替代真实访谈。但 AI 非常适合在访谈前、中、后给你打辅助，尤其适合帮新手降低门槛。</p><h3 id="_12-1-让-ai-帮你把-容易问废-的问题改写掉" tabindex="-1">12.1 让 AI 帮你把“容易问废”的问题改写掉 <a class="header-anchor" href="#_12-1-让-ai-帮你把-容易问废-的问题改写掉" aria-label="Permalink to “12.1 让 AI 帮你把“容易问废”的问题改写掉”">​</a></h3><p>很多人知道自己不该问“你觉得我这个想法怎么样”，但一开口还是会回到这种句子。你可以先把自己准备问的问题交给 AI，让它帮你改写：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我准备做用户访谈时想问的问题：</span></span>
<span class="line"><span>[贴上你的问题]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请你用 The Mom Test 的原则帮我改写：</span></span>
<span class="line"><span>1. 删掉意见型问题</span></span>
<span class="line"><span>2. 删掉假设未来的问题</span></span>
<span class="line"><span>3. 尽量改成围绕过去真实行为、已有替代方案和已付成本的提问</span></span>
<span class="line"><span>4. 最后整理成一套 8-10 个可以直接访谈的问题清单</span></span></code></pre></div><p>一个很小白的输入也完全可以：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想问用户：</span></span>
<span class="line"><span>1. 你觉得我做一个 AI 改简历工具怎么样？</span></span>
<span class="line"><span>2. 你会不会用？</span></span>
<span class="line"><span>3. 你愿不愿意付费？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请帮我改成更好的问法。</span></span></code></pre></div><p>AI 可能给出的有用输出会像这样：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>改写后的问题：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 你最近一次改简历是什么时候？</span></span>
<span class="line"><span>2. 当时为什么要改？</span></span>
<span class="line"><span>3. 你是怎么改的？</span></span>
<span class="line"><span>4. 哪一步最花时间？</span></span>
<span class="line"><span>5. 你有没有找别人帮你看？</span></span>
<span class="line"><span>6. 你以前有没有为简历修改花过钱或花过很多时间？</span></span></code></pre></div><p>这种输出很有帮助，因为它直接把你原本“在问意见”的问题，改成了“在问真实行为”的问题。</p><h3 id="_12-2-让-ai-帮你生成不同对象的访谈提纲" tabindex="-1">12.2 让 AI 帮你生成不同对象的访谈提纲 <a class="header-anchor" href="#_12-2-让-ai-帮你生成不同对象的访谈提纲" aria-label="Permalink to “12.2 让 AI 帮你生成不同对象的访谈提纲”">​</a></h3><p>同一个方向，面对不同人群，访谈重点会不一样。比如学生、HR、自由职业者，关心点完全不同。你可以让 AI 帮你针对不同对象各出一版提纲：</p><ul><li>面向新手用户，重点了解最近一次真实经历</li><li>面向重度用户，重点了解替代方案和痛感</li><li>面向付费用户，重点了解是否已经为此付过成本</li></ul><p>这样你在真正聊天时会更有节奏，而不会每个人都问同一套问题。</p><p>比如你可以直接这样输入：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我要聊两类人：</span></span>
<span class="line"><span>1. 第一次找实习的大学生</span></span>
<span class="line"><span>2. 已经帮别人看过很多简历的学长学姐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请分别给我一套访谈提纲，每套 6 个问题。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对大学生：</span></span>
<span class="line"><span>1. 最近一次投实习是什么时候？</span></span>
<span class="line"><span>2. 当时最卡的是哪一步？</span></span>
<span class="line"><span>3. 你怎么知道自己的简历能不能投？</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对学长学姐：</span></span>
<span class="line"><span>1. 你最近一次帮别人看简历是什么时候？</span></span>
<span class="line"><span>2. 你最常看到哪些明显问题？</span></span>
<span class="line"><span>3. 学弟学妹最容易卡在哪一步？</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这样一来，你不用自己从零编问题，访谈准备会轻松很多。</p><h3 id="_12-3-让-ai-帮你整理访谈记录" tabindex="-1">12.3 让 AI 帮你整理访谈记录 <a class="header-anchor" href="#_12-3-让-ai-帮你整理访谈记录" aria-label="Permalink to “12.3 让 AI 帮你整理访谈记录”">​</a></h3><p>访谈做完之后，最容易出现的问题不是“没信息”，而是“信息太散”。AI 很适合帮你把碎片化对话整理成结构化笔记：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我和 3 位用户的访谈记录。</span></span>
<span class="line"><span>请按 The Mom Test 的角度整理：</span></span>
<span class="line"><span>1. 哪些内容是事实，哪些只是意见</span></span>
<span class="line"><span>2. 用户最近一次真实行为是什么</span></span>
<span class="line"><span>3. 当前替代方案是什么</span></span>
<span class="line"><span>4. 用户已经付出的时间、金钱或精力成本是什么</span></span>
<span class="line"><span>5. 哪些问题被反复提到</span></span>
<span class="line"><span>6. 哪些说法听起来积极，但证据不足</span></span></code></pre></div><p>这一步尤其有价值，因为它能帮你把“听起来不错”的内容和“真的能支撑判断”的内容分开。</p><p>一个简单输入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这是我和一个用户聊完后的记录：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 她说如果有个工具应该会试试</span></span>
<span class="line"><span>- 她上周为了改简历花了一个晚上</span></span>
<span class="line"><span>- 她现在主要靠朋友帮看</span></span>
<span class="line"><span>- 她说最难的是不知道改到什么程度算可以投</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请你帮我分一下，哪些是意见，哪些是事实。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>意见：</span></span>
<span class="line"><span>- 如果有个工具应该会试试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>事实：</span></span>
<span class="line"><span>- 上周为了改简历花了一个晚上</span></span>
<span class="line"><span>- 当前替代方案是找朋友帮看</span></span>
<span class="line"><span>- 最难点是不知道什么时候算“可以投”</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可用于判断需求的重点：</span></span>
<span class="line"><span>- 这个问题最近刚发生过</span></span>
<span class="line"><span>- 用户已经投入了明显时间成本</span></span>
<span class="line"><span>- 当前方案依赖他人，不稳定</span></span></code></pre></div><p>这个输出就能很直观地告诉新手：哪些话能拿来做判断，哪些话只能听听。</p><h3 id="_12-4-让-ai-先做一轮轻量级网络搜索" tabindex="-1">12.4 让 AI 先做一轮轻量级网络搜索 <a class="header-anchor" href="#_12-4-让-ai-先做一轮轻量级网络搜索" aria-label="Permalink to “12.4 让 AI 先做一轮轻量级网络搜索”">​</a></h3><p>如果你还没开始访谈，可以先让 AI 帮你做一些很轻的外部调研，比如：</p><ul><li>公开社区里，大家最近是怎么抱怨这个问题的</li><li>现有工具被吐槽最多的是什么</li><li>用户是不是已经为相似问题花过钱</li><li>市场上有哪些替代方案已经存在</li></ul><p>这类信息不能替代真人访谈，但能帮你更快进入状态，知道该从哪里切入问题。</p><p>比如一个简单输入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请你帮我搜一下：</span></span>
<span class="line"><span>“大学生改简历时最常吐槽什么”</span></span>
<span class="line"><span>帮我整理出 5 条最常见抱怨，用很白话的话写出来。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>常见抱怨：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 不知道简历上到底该写什么</span></span>
<span class="line"><span>2. 每投一个岗位都要改，太累</span></span>
<span class="line"><span>3. 改了很多版还是不确定好不好</span></span>
<span class="line"><span>4. 没人能给靠谱反馈</span></span>
<span class="line"><span>5. 总觉得还没准备好，所以一直拖</span></span></code></pre></div><p>这种结果的价值在于，它会让你更容易找到访谈切入口。</p><h3 id="_12-5-让-ai-扮演-访谈复盘教练" tabindex="-1">12.5 让 AI 扮演“访谈复盘教练” <a class="header-anchor" href="#_12-5-让-ai-扮演-访谈复盘教练" aria-label="Permalink to “12.5 让 AI 扮演“访谈复盘教练””">​</a></h3><p>你还可以把自己刚做完的一场访谈记录丢给 AI，让它帮你挑刺：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我的一段用户访谈记录。</span></span>
<span class="line"><span>请从 The Mom Test 的角度帮我复盘：</span></span>
<span class="line"><span>1. 我哪些问题问得太像在找认可</span></span>
<span class="line"><span>2. 哪些问题带有明显引导</span></span>
<span class="line"><span>3. 哪些地方本来可以继续追问事实</span></span>
<span class="line"><span>4. 如果再来一次，这段对话可以怎么问得更好</span></span></code></pre></div><p>这对新手特别有帮助，因为你会更快建立一种“我到底是在收集证据，还是在收集鼓励”的敏感度。</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>请你根据上文内容，完成下列作业：</p><ol><li>选一个你最近想做的产品方向，先写出 5 个你原本会问的“容易问废”的问题</li><li>把这 5 个问题改写成更符合 The Mom Test 风格的提问</li><li>找 3 个潜在用户，至少问出一次“最近一次你遇到这个问题是什么时候”</li><li>访谈结束后整理 4 类信息：真实行为、替代方案、已付成本、反复出现的困难</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test 官方网站</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,185))])}}});export{u as __pageData,m as default};
